from taf.ul.ettf.context import context
from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.exception import LibraryError


logger = custom_logger('simulator_library')


class DummyCommand(Command):
    def __init__(self):
        super(DummyCommand, self).__init__(None, None)


class CommandBuildingNotFinishedYet(LibraryError):
    def __init__(self, msg):
        super(CommandBuildingNotFinishedYet, self).__init__('ANOTHER COMMAND IS ALREADY BEING BUILT', msg)


class CommandBuildingNotStartedYet(LibraryError):
    def __init__(self, msg):
        super(CommandBuildingNotStartedYet, self).__init__('BUILDING COMMAND IS NOT STARTED YET', msg)


def name(class_instance):
    return class_instance.__class__.__name__


def error_message(lib_instance, simulator):
    return '{}: There is no such simulator available: {}'.format(name(lib_instance), simulator)


class CommandBuilder(object):
    def __init__(self):
        self._command = None

    def started(self):
        return self._command is not None

    def command(self):
        return self._command

    def start(self):
        self._command = DummyCommand()
        return self

    def finish(self):
        return self._command

    def clear(self):
        self.remove_validators()
        self._command = None

    def init_command(self, command):
        self._command = command
        return self

    def with_command_attribute(self, param_name, param_value):
        self._command.add_param(param_name, param_value)
        return self

    def replace_validators(self, validators):
        self._command.replace_validators(validators)
        return self

    def add_validator(self, validator):
        self._command.add_validator(validator)
        return self

    def remove_validators(self):
        if self._command:
            self._command.remove_validators()

    def add_measurement(self, measurement):
        self._command.add_measurement(measurement)

    def add_phycell(self, phycell):
        self._command.add_phycell(phycell)

    def extend_base_command(self, expression):
        self._command.extend_base(expression)


def with_simulator():
    def deco(func):
        def wrapped(self, *args, **kwargs):
            context.simulator.connect()
            result = func(self, context.simulator, *args, **kwargs)
            context.simulator.disconnect()
            return result
        return wrapped
    return deco


command_builder = CommandBuilder()


def replace_builder(builder):
    global command_builder
    command_builder = builder


def clear_builder():
    command_builder.clear()


class State(object):
    def start(self):
        if command_builder.started():
            raise CommandBuildingNotFinishedYet(
                'Before building another command finish the one which is already being built: {}'.format(
                    command_builder.command().command))
        replace_builder(CommandBuilder())
        command_builder.start()

    @with_simulator()
    def finalize(self, simulator):
        if not command_builder.started():
            raise CommandBuildingNotStartedYet('Start building command first')
        try:
            command = command_builder.command()
            output = command.run(simulator)
        finally:
            command_builder.clear()
        return output

    @with_simulator()
    def init_command(self, simulator, command):
        if command_builder.started():
            command_builder.init_command(command)
        else:
            return command.run(simulator)

    @with_simulator()
    def init_simple_command(self, simulator, command):
        if command_builder.started():
            command_builder.init_command(command)
        else:
            return command.run(simulator).first()

    def with_parameter(self, parameter_name, parameter_value):
        self.append_command_attribute(parameter_name, parameter_value)

    def with_parameters(self, **parameters):
        for parameter_name, parameter_value in parameters.items():
            self.append_command_attribute(parameter_name, parameter_value)

    @staticmethod
    def add_measurement(measurement):
        command_builder.add_measurement(measurement)

    @staticmethod
    def add_phycell(phycell):
        command_builder.add_phycell(phycell)

    @staticmethod
    def append_command_attribute(attribute_name, attribute_value):
        command_builder.with_command_attribute(attribute_name, attribute_value)

    @staticmethod
    def replace_validators(validators):
        command_builder.replace_validators(validators)

    @staticmethod
    def add_validator(validator):
        command_builder.add_validator(validator)

    @staticmethod
    def extend_base_command(expression):
        command_builder.extend_base_command(expression)
